<template>
  <div id="app">
    <h1>Herbal Flashcards 🌿</h1>
    <div class="flashcards">
      <Flashcard v-for="(herb, index) in herbs" :key="index" :herb="herb" />
    </div>
  </div>
</template>

<script>
import Flashcard from "./components/FlashCard.vue";

export default {
  components: { Flashcard },
  data() {
    return {
      herbs: [], // Empty initially, will be populated later
    };
  },
  mounted() {
    this.loadHerbsData();
  },
  methods: {
    async loadHerbsData() {
      try {
        // Set base URL dynamically for local vs production
        let baseUrl = process.env.NODE_ENV === 'production' ? '/ttm-app' : '';
        console.log("Base URL:", baseUrl);

        // Fetch the herbs.json file based on environment
        const response = await fetch(`${baseUrl}/herbs.json`); // Adjust path based on baseUrl
        if (!response.ok) {
          throw new Error(`Failed to fetch herbs data: ${response.statusText}`);
        }

        // Parse JSON data
        const data = await response.json();

        // Update the image paths based on the baseUrl
        data.forEach(herb => {
          herb.image = `${baseUrl}/${herb.image}`;
        });

        // Set the herbs data to be used in the template
        this.herbs = data;
      } catch (error) {
        console.error('Error loading herbs data:', error);
      }
    }
  },
};
</script>

<style>
#app {
  text-align: center;
  font-family: Arial, sans-serif;
}
.flashcards {
  display: flex;
  justify-content: center;
  gap: 20px;
  flex-wrap: wrap;
}
